	if adapterName == "caddyfile" {
		return true, nil
	}

	// If an adapter was explicitly specified, we should not try to
	// auto-detect the Caddyfile adapter.
	if adapterName != "" {
		return false, nil
	}

	// As a special case, if a config file starts with "caddyfile" or
	// has a ".caddyfile" extension, assume the caddyfile adapter for
	// convenience, regardless of the file extension.
	baseConfig := strings.ToLower(filepath.Base(configFile))
	baseConfigExt := filepath.Ext(baseConfig)

	// JSON config files should always be treated as JSON, not Caddyfile.
	if baseConfigExt == ".json" {
		return false, nil
	}

	if strings.HasPrefix(baseConfig, "caddyfile") || strings.HasSuffix(baseConfig, ".caddyfile") {
		return true, nil
	}

	return false, nil
}

'''
